  },
] satisfies RowListItemDescriptor[];

function getDescriptor(item: unknown): RowListItemDescriptor {
  return item as RowListItemDescriptor;
}

const meta = {
  args: {
    'aria-label': 'Activity',
    getItem: getDescriptor,
    items: entries,
    loadMore: {
      label: 'Load more activity',
      onAction: fn(),
    },
